import{_ as e,o as a,c as s,a0 as n}from"./chunks/framework.BQGW-Zpy.js";const m=JSON.parse('{"title":"Settlement Speed by Corridor","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/settlement-speed.md","filePath":"architecture/settlement-speed.md"}'),i={name:"architecture/settlement-speed.md"};function r(d,t,o,l,c,h){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="settlement-speed-by-corridor" tabindex="-1">Settlement Speed by Corridor <a class="header-anchor" href="#settlement-speed-by-corridor" aria-label="Permalink to &quot;Settlement Speed by Corridor&quot;">​</a></h1><p>Delivery time is driven by which <strong>local instant-payment rail</strong> the destination currency actually has, not a flat estimate for every bank transfer. Mobile money already settles in minutes; a bank transfer to a currency with a confirmed instant rail is seconds, not days. Where no instant rail is confirmed, we show a conservative standard-transfer estimate rather than guessing.</p><h2 id="verified-rails-by-currency-this-platform-supports" tabindex="-1">Verified rails, by currency this platform supports <a class="header-anchor" href="#verified-rails-by-currency-this-platform-supports" aria-label="Permalink to &quot;Verified rails, by currency this platform supports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Currency</th><th>Country</th><th>Rail</th><th>Settlement</th><th>Source</th></tr></thead><tbody><tr><td>EUR</td><td>Eurozone</td><td>SEPA Instant</td><td>&lt; 10 sec</td><td>EPC</td></tr><tr><td>USD</td><td>United States</td><td>RTP / FedNow</td><td>seconds</td><td>The Clearing House / Federal Reserve</td></tr><tr><td>GBP</td><td>United Kingdom</td><td>Faster Payments</td><td>&lt; 2 min</td><td>Pay.UK</td></tr><tr><td>INR</td><td>India</td><td>UPI</td><td>&lt; 10 sec</td><td>NPCI</td></tr><tr><td>BRL</td><td>Brazil</td><td>Pix</td><td>&lt; 10 sec</td><td>Banco Central do Brasil</td></tr><tr><td>MXN</td><td>Mexico</td><td>SPEI</td><td>&lt; 30 sec</td><td>Banco de México</td></tr><tr><td>SGD</td><td>Singapore</td><td>FAST / PayNow</td><td>&lt; 1 min</td><td>MAS</td></tr><tr><td>NGN / GHS / UGX / TZS</td><td>Nigeria, Ghana, Uganda, Tanzania</td><td>Mobile Money</td><td>~2 min</td><td>Local telco rails</td></tr><tr><td>KES</td><td>Kenya</td><td>Mobile Money (M-Pesa)</td><td>~1 min</td><td>Safaricom</td></tr><tr><td>BDT</td><td>Bangladesh</td><td>Mobile Money (bKash)</td><td>~2 min</td><td>bKash</td></tr></tbody></table><p>Every other supported currency defaults to <strong>1–2 business days via standard bank transfer</strong>, stated as an estimate, not dressed up as a confirmed instant rail we haven&#39;t verified.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This table lives in code, not just documentation: <code>frontend/src/data/settlementSpeed.js</code>. The &quot;Estimated delivery&quot; field on the transfer summary reads from it live, pick EUR as the receiving currency and the summary shows &quot;10 seconds (SEPA Instant)&quot;, not a generic default.</p></div><h2 id="why-the-stablecoin-leg-is-fast-but-not-the-whole-story" tabindex="-1">Why the stablecoin leg is fast but not the whole story <a class="header-anchor" href="#why-the-stablecoin-leg-is-fast-but-not-the-whole-story" aria-label="Permalink to &quot;Why the stablecoin leg is fast but not the whole story&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as Sender</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant P as Licensed PSP</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant H as Hedera (trust anchor)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant L as Licensed payout partner</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant R as Recipient&#39;s bank</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;P: Pays in local fiat (card/SEPA)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P-&gt;&gt;H: Compliance check anchored (HCS)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    P-&gt;&gt;L: Stablecoin settlement (~3s, Hedera)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    H-&gt;&gt;H: Routing decision anchored (HCS)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L-&gt;&gt;R: Local instant rail (SEPA Instant / PIX / UPI / mobile money)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    R--&gt;&gt;L: Confirmation of Payee check</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    L--&gt;&gt;P: Settlement confirmed</span></span></code></pre></div><p>The Hedera leg (compliance anchor + stablecoin transfer) is genuinely fast, seconds, deterministic. But the number the sender actually cares about is the <strong>last mile</strong>: whether the destination currency has its own instant rail. That is what <code>settlementSpeed.js</code> reports corridor by corridor.</p><h2 id="what-this-does-not-claim" tabindex="-1">What this does <em>not</em> claim <a class="header-anchor" href="#what-this-does-not-claim" aria-label="Permalink to &quot;What this does *not* claim&quot;">​</a></h2><p>Anchoring a compliance or routing decision on Hedera proves that record hasn&#39;t been tampered with. <strong>It does not prove the money has landed in the recipient&#39;s account</strong>, that confirmation still comes from the destination bank, via the local rail above or a traditional SWIFT confirmation where no instant rail exists. These are two separate guarantees; conflating them would be a real overclaim. See <a href="./payee-verification.html">Payee Verification &amp; Failed Settlement</a> for the reconciliation path when that final confirmation doesn&#39;t arrive.</p>`,11)])])}const y=e(i,[["render",r]]);export{m as __pageData,y as default};
